(async () => {
  const f = fixtureApp.features, p = fixtureApp.ports;
  const results = [];
  const delay = () => new Promise(resolve => setTimeout(resolve, 0));
  const until = async predicate => { for (let i = 0; i < 200; i++) { if (predicate()) return; await delay(); } throw new Error('Probe did not reach held body'); };
  p.appBindings.actions.closeSettingsModal();
  for (const initial of ['neither', 'search', 'subagents']) {
    for (const order of [['search', 'subagents'], ['subagents', 'search']]) {
      f.searchViewController.close(); f.subagentsController.close();
      const owner = f.sessionState.captureSelection();
      const releases = [];
      const port = initial === 'search' ? p.searchViewController : p.subagentsController;
      const originalRequest = port.request;
      let held = false;
      const pending = [];
      if (initial !== 'neither') {
        port.request = (...args) => {
          const request = originalRequest(...args).then(async response => {
            const data = await response.json();
            if (initial === 'search') for (const row of data.results || []) row.name = 'LATE_SEARCH_COMMUTATION';
            else if (data.tree) data.tree.session.name = 'LATE_SUBAGENTS_COMMUTATION';
            held = true;
            await new Promise(resolve => releases.push(resolve));
            return new Response(JSON.stringify(data), { status: response.status });
          });
          pending.push(request); return request;
        };
      }
      try {
        if (initial === 'search') f.searchViewController.open('isolated');
        if (initial === 'subagents') f.subagentsController.open(owner, p.subagentsController.endpoint(owner.host), { session: null, tree: null, members: 0, truncated: false });
        if (initial !== 'neither') await until(() => held);
        const before = { search: document.querySelector('#searchViewBody').innerHTML, tree: document.querySelector('#subagentsTree').innerHTML };
        for (const name of order) (name === 'search' ? f.searchViewController : f.subagentsController).close();
        for (const release of releases) release();
        await Promise.all(pending); await delay();
        // Static retained controls must not reopen or navigate after retirement.
        document.querySelector('#subagentsOpenBtn').click();
        document.querySelector('#subagentsSendBtn').click();
        f.searchViewController.setToken('cwd', '/retired');
        await delay();
        const after = { search: document.querySelector('#searchViewBody').innerHTML, tree: document.querySelector('#subagentsTree').innerHTML };
        const row = { initial, order, heldResponses: pending.length, searchOpen: f.searchViewController.isOpen(), subagentsOpen: f.subagentsController.isOpen(),
          bodiesUnchanged: before.search === after.search && before.tree === after.tree,
          lateMarkersRejected: !after.search.includes('LATE_SEARCH_COMMUTATION') && !after.tree.includes('LATE_SUBAGENTS_COMMUTATION'),
          selectionUnchanged: f.sessionState.ownsSelection(owner),
          retainedActionsInert: document.querySelector('#searchViewInput').value !== 'cwd:/retired',
          classes: [...document.querySelector('.main').classList].sort() };
        if (row.searchOpen || row.subagentsOpen || !row.bodiesUnchanged || !row.lateMarkersRejected || !row.selectionUnchanged || !row.retainedActionsInert) throw new Error(JSON.stringify(row));
        results.push(row);
      } finally { port.request = originalRequest; for (const release of releases) release(); }
    }
  }
  return results;
})()

