const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const root = '/home/jyarwood/workspace/pi-dish-r8';
const esbuild = require(root + '/node_modules/esbuild');
const espree = require(root + '/node_modules/espree');
const source = esbuild.transformSync(fs.readFileSync(root + '/src/browser/app.ts', 'utf8'), { loader: 'ts', target: 'es2022' }).code;
const tree = espree.parse(source, { ecmaVersion: 'latest', sourceType: 'module', range: true });
let registration;
for (const statement of tree.body) {
  if (statement.type !== 'VariableDeclaration') continue;
  for (const declaration of statement.declarations) {
    if (declaration.id.name === 'mainPane') registration = declaration.init.arguments[0];
  }
}
assert(registration);
const takeovers = registration.properties.find(property => property.key.name === 'takeovers').value;
// The only contributor edit: one new takeover registration, in memory only.
const insertAt = takeovers.range[1] - 1 - registration.range[0];
const original = source.slice(...registration.range);
const extended = original.slice(0, insertAt) + ", audit: { close: () => auditController.close() }\n" + original.slice(insertAt);
const state = new Set();
let closes = 0;
const names = ['usageController', 'searchViewController', 'subagentsController', 'newSessionController', 'skillsController', 'routinesController', 'recoveryController', 'auditController'];
const context = {};
for (const name of names) context[name] = { close() { closes++; state.delete(name); } };
for (const [name, methods] of Object.entries({ sessionSearch: ['close'], fileViews: ['closeDiff', 'closeFile'], sidebarQuery: ['close'], sessionInfo: ['closeStats', 'closeArtifacts'], transcriptTree: ['close'], sessionControls: ['closeModels', 'closeThinking'], bounceController: ['close'] })) {
  context[name] = Object.fromEntries(methods.map(method => [method, () => {}]));
}
context.closeSettingsModal = () => {};
const policies = vm.runInNewContext('(' + extended + ')', context);
const moduleObject = { exports: {} };
vm.runInNewContext(esbuild.transformSync(fs.readFileSync(root + '/src/browser/main-pane.ts', 'utf8'), { loader: 'ts', format: 'cjs' }).code, { module: moduleObject });
const pane = moduleObject.exports.createMainPane(policies);
const cases = [];
for (const [index, name] of Object.keys(policies.takeovers).entries()) {
  for (const controller of names) state.add(controller);
  closes = 0;
  pane.beforeTakeover(name);
  assert.deepEqual([...state], [names[index]]);
  cases.push({ opening: name, retained: [...state], closeCalls: closes });
}
state.add('auditController'); pane.beforeSelection(false); assert.equal(state.size, 0);
console.log(JSON.stringify({ change: 'One in-memory audit takeover registration in the actual app policy table; no existing peer edits', cases, selectionRetiresAddedTakeover: true }, null, 2));

